import Foundation
import XCTest
@testable import HongyanCore

/// End-to-end against a real S3-compatible bucket (Cloudflare R2). Skipped
/// unless these environment variables are set:
///
///     HONGYAN_IT_ACCOUNT_ID   R2 account id (endpoint https://<id>.r2.cloudflarestorage.com)
///     HONGYAN_IT_BUCKET       bucket to write into (a random test prefix is used and removed)
///     HONGYAN_IT_KEY / HONGYAN_IT_SECRET
///
/// The engine is the real one; `HTTPPutQueue` plays the part of iOS's upload
/// service and PUTs generated bytes to the presigned URLs.
final class R2IntegrationTests: XCTestCase {
    var client: S3Client!
    var config: S3Config!
    var prefix = ""
    var dir: TempDir!
    var library: FakeLibrary!
    var queue: HTTPPutQueue!
    var settings: BackupSettings!
    var clock: FixedClock!

    override func setUpWithError() throws {
        let env = ProcessInfo.processInfo.environment
        guard let account = env["HONGYAN_IT_ACCOUNT_ID"], let bucket = env["HONGYAN_IT_BUCKET"],
              let key = env["HONGYAN_IT_KEY"], let secret = env["HONGYAN_IT_SECRET"], !account.isEmpty else {
            throw XCTSkip("Set HONGYAN_IT_* to run against a real bucket")
        }
        prefix = "hongyan-it/\(UUID().uuidString.prefix(8).lowercased())"
        config = S3Config(endpoint: URL(string: "https://\(account).r2.cloudflarestorage.com")!, region: "auto",
                          bucket: bucket, prefix: prefix, usePathStyle: true)
        client = S3Client(config: config, credentials: S3Credentials(accessKeyID: key, secretAccessKey: secret),
                          transport: URLSessionTransport())
        dir = TempDir()
        library = FakeLibrary()
        queue = HTTPPutQueue(jobLimit: 6)
        clock = FixedClock(Date())
        settings = BackupSettings(s3: config, intervalDays: 1, keepLatest: 1)
        report("bucket \(bucket), prefix \(prefix)/")
    }

    override func tearDown() async throws {
        guard let client else { return }
        let keys = try await client.listAllKeys(prefix: prefix + "/")
        for start in stride(from: 0, to: keys.count, by: 1000) {
            _ = try await client.deleteObjects(keys: Array(keys[start..<min(start + 1000, keys.count)]))
        }
        let left = try await client.listAllKeys(prefix: prefix + "/")
        report("cleanup: deleted \(keys.count) objects, \(left.count) left")
    }

    func report(_ line: String) { print("[R2] \(line)") }

    func engine(_ store: StateStore) -> BackupEngine {
        BackupEngine(settings: settings, credentials: client.credentials, library: library, queue: queue,
                     remote: S3SnapshotStore(client: client, layout: KeyLayout(prefix: prefix)), store: store,
                     clock: clock, transport: URLSessionTransport())
    }

    /// Engine passes until idle, letting the real uploads finish in between.
    @discardableResult
    func runRound(_ store: StateStore, force: Bool = true) async throws -> EngineState {
        if force { try engine(store).requestBackupNow() }
        for _ in 0..<100 {
            let outcome = await engine(store).run()
            if case .failure(let reason) = outcome { XCTFail("engine failure: \(reason)"); break }
            if outcome == .completed { break }
            try await queue.waitUntilIdle()
        }
        clock.advance(by: 2)
        return try store.load()
    }

    func libraryKeys() async throws -> [String] {
        try await client.listAllKeys(prefix: KeyLayout(prefix: prefix).libraryRoot)
    }

    func testDeltaSyncAgainstRealBucket() async throws {
        let store = try FileStateStore(directory: dir.url)
        let layout = KeyLayout(prefix: prefix)
        for i in 0..<5 { library.addPhoto("photo-\(i)") }
        library.addPhoto("live-0", live: true)

        // 1. First sync: everything.
        var state = try await runRound(store)
        var last = try XCTUnwrap(state.lastCompleted)
        var keys = try await libraryKeys()
        report("round 1: uploaded \(last.uploadedFiles), unchanged \(last.unchangedFiles ?? 0); bucket has \(keys.count) files")
        XCTAssertEqual(last.uploadedFiles, 7)
        XCTAssertEqual(keys.count, 7)
        let remoteIndex = try await S3SnapshotStore(client: client, layout: layout).loadSyncIndex(key: layout.syncIndexKey)
        XCTAssertEqual(remoteIndex?.entries.count, 7, "index.json in the bucket")
        let roundRecord = try await client.getObject(key: layout.roundRecordKey(last.id))
        XCTAssertNotNil(roundRecord, "round record in the bucket")
        let sampleKey = try XCTUnwrap(keys.first)
        let body = try await client.getObject(key: sampleKey)
        XCTAssertEqual(body, queue.sentBodies[sampleKey], "bytes in the bucket match what was sent")

        // 2. Nothing changed: nothing uploaded.
        state = try await runRound(store)
        last = try XCTUnwrap(state.lastCompleted)
        report("round 2 (no changes): uploaded \(last.uploadedFiles), unchanged \(last.unchangedFiles ?? 0)")
        XCTAssertEqual(last.uploadedFiles, 0)
        XCTAssertEqual(last.unchangedFiles, 7)

        // 3. One new photo, one edited photo: two uploads.
        library.addPhoto("photo-new")
        library.modify("photo-2", at: Date().addingTimeInterval(100))
        state = try await runRound(store)
        last = try XCTUnwrap(state.lastCompleted)
        keys = try await libraryKeys()
        report("round 3 (1 new, 1 edited): uploaded \(last.uploadedFiles), unchanged \(last.unchangedFiles ?? 0); bucket has \(keys.count) files")
        XCTAssertEqual(last.uploadedFiles, 2)
        XCTAssertEqual(keys.count, 8)

        // 4. A file disappears from the bucket: verify finds it and uploads it again.
        _ = try await client.deleteObjects(keys: [sampleKey])
        state = try await runRound(store)
        last = try XCTUnwrap(state.lastCompleted)
        report("round 4 (1 deleted in bucket): missing \(last.missingRemote ?? 0), uploaded \(last.uploadedFiles)")
        XCTAssertEqual(last.missingRemote, 1)
        XCTAssertEqual(last.uploadedFiles, 1)
        let restored = try await client.getObject(key: sampleKey)
        XCTAssertNotNil(restored)

        // 5. Local state lost (new install): continue from index.json, no uploads.
        let fresh = TempDir()
        let freshStore = try FileStateStore(directory: fresh.url)
        state = try await runRound(freshStore)
        last = try XCTUnwrap(state.lastCompleted)
        report("round 5 (local state wiped): uploaded \(last.uploadedFiles), unchanged \(last.unchangedFiles ?? 0)")
        XCTAssertEqual(last.uploadedFiles, 0)
        XCTAssertEqual(last.unchangedFiles, 8)

        // 6. Index gone too: files in the bucket are adopted, not uploaded.
        _ = try await client.deleteObjects(keys: [layout.syncIndexKey])
        let fresh2 = TempDir()
        let store2 = try FileStateStore(directory: fresh2.url)
        state = try await runRound(store2)
        last = try XCTUnwrap(state.lastCompleted)
        report("round 6 (local state and index.json gone): adopted \(last.adoptedFiles ?? 0), uploaded \(last.uploadedFiles)")
        XCTAssertEqual(last.uploadedFiles, 0)
        XCTAssertEqual(last.adoptedFiles, 8)

        // 7. Interrupted round: one pass, "crash", new engine, continue.
        for i in 0..<4 { library.addPhoto("late-\(i)") }
        let duplicatesBefore = queue.duplicatePuts
        queue.jobLimit = 2
        try engine(store2).requestBackupNow()
        _ = await engine(store2).run()
        try await queue.waitUntilIdle()
        let sentBefore = queue.sentBodies.count
        state = try await runRound(try FileStateStore(directory: fresh2.url), force: false)
        last = try XCTUnwrap(state.lastCompleted)
        keys = try await libraryKeys()
        report("round 7 (interrupted after 1 pass, continued): uploaded \(last.uploadedFiles) in total; bucket has \(keys.count) files; duplicate PUTs \(queue.duplicatePuts - duplicatesBefore)")
        XCTAssertEqual(last.uploadedFiles, 4)
        XCTAssertEqual(keys.count, 12)
        XCTAssertEqual(queue.duplicatePuts - duplicatesBefore, 0)
        XCTAssertGreaterThan(queue.sentBodies.count, sentBefore)
    }

    func testFullCopiesAndRetentionAgainstRealBucket() async throws {
        settings.mode = .snapshot
        settings.keepLatest = 1
        let store = try FileStateStore(directory: dir.url)
        for i in 0..<3 { library.addPhoto("photo-\(i)") }
        try await runRound(store)
        try await runRound(store)
        let snapshots = try await S3SnapshotStore(client: client, layout: KeyLayout(prefix: prefix)).listSnapshots()
        report("full copies: 2 rounds, keep latest 1 → \(snapshots.count) snapshot(s) in the bucket, complete: \(snapshots.map(\.isComplete))")
        XCTAssertEqual(snapshots.count, 1)
        XCTAssertEqual(snapshots.first?.isComplete, true)
    }
}

/// Stands in for iOS's background upload service: PUTs generated bytes to
/// each job's presigned URL with a real HTTP client.
final class HTTPPutQueue: UploadJobQueue, @unchecked Sendable {
    var jobLimit: Int
    private let lock = NSLock()
    private var jobs: [String: (url: URL, state: UploadJobState, code: Int?)] = [:]
    private(set) var sentBodies: [String: Data] = [:]
    private(set) var duplicatePuts = 0
    private let transport = URLSessionTransport()

    init(jobLimit: Int) { self.jobLimit = jobLimit }

    func finishedJobs() throws -> [UploadJobInfo] {
        lock.lock(); defer { lock.unlock() }
        return jobs.compactMap { id, job in
            guard job.state == .succeeded || job.state == .failed else { return nil }
            return UploadJobInfo(id: id, destination: job.url, state: job.state,
                                 errorDomain: job.code == nil ? nil : "HTTP", errorCode: job.code)
        }
    }

    func processingJobCount() throws -> Int? {
        lock.lock(); defer { lock.unlock() }
        return jobs.values.filter { $0.state == .pending }.count
    }

    func acknowledge(jobIDs: [String]) throws {
        lock.lock(); defer { lock.unlock() }
        for id in jobIDs { jobs[id] = nil }
    }

    func create(_ newJobs: [NewUploadJob]) throws {
        lock.lock()
        guard jobs.count + newJobs.count <= jobLimit else { lock.unlock(); throw UploadJobQueueError.limitExceeded }
        var started: [(String, NewUploadJob)] = []
        for job in newJobs {
            let id = UUID().uuidString
            jobs[id] = (job.destination.url, .pending, nil)
            started.append((id, job))
        }
        lock.unlock()
        for (id, job) in started {
            Task { await self.put(id: id, job: job) }
        }
    }

    func waitUntilIdle() async throws {
        for _ in 0..<600 {
            if try processingJobCount() == 0 { return }
            try await Task.sleep(nanoseconds: 100_000_000)
        }
        XCTFail("uploads did not finish in 60 s")
    }

    private func put(id: String, job: NewUploadJob) async {
        let seed = "\(job.assetID)/\(job.resource.index)/\(job.resource.originalFilename)"
        let size = 2_048 + abs(seed.hashValue % 30_000)
        var body = Data(capacity: size)
        while body.count < size { body.append(contentsOf: Array(seed.utf8)) }
        body = body.prefix(size)
        var request = job.destination
        request.body = body
        var state: UploadJobState = .failed
        var code: Int?
        do {
            let response = try await transport.send(request)
            state = response.isSuccess ? .succeeded : .failed
            code = response.isSuccess ? nil : response.status
        } catch {
            code = (error as NSError).code
        }
        let key = job.destination.url.path
        record(id: id, path: key, body: body, state: state, code: code)
    }

    private func record(id: String, path: String, body: Data, state: UploadJobState, code: Int?) {
        lock.lock(); defer { lock.unlock() }
        if state == .succeeded {
            let objectKey = String(path.drop(while: { $0 == "/" }).split(separator: "/", maxSplits: 1).last ?? "")
            let decoded = objectKey.removingPercentEncoding ?? objectKey
            if sentBodies[decoded] != nil { duplicatePuts += 1 }
            sentBodies[decoded] = body
        }
        jobs[id]?.state = state
        jobs[id]?.code = code
    }
}
